<script setup lang="ts">
import { computed } from 'vue'
import type { Dictionary, MatrixCell } from '../api/types'
const props=defineProps<{colors:Dictionary[];sizes:Dictionary[];modelValue:MatrixCell[];productCode:string;readonlyDimensions?:boolean;allowReceiving?:boolean;disabled?:boolean}>()
const emit=defineEmits<{ 'update:modelValue':[MatrixCell[]] }>()
const map=computed(()=>new Map(props.modelValue.map(c=>[`${c.color_id}:${c.size_id}`,c])))
function value(color:number,size:number){return map.value.get(`${color}:${size}`)}
const rows=computed(()=>props.colors.flatMap(color=>props.sizes.map(size=>({color,size,cell:value(color.id,size.id)}))).filter(row=>row.cell))
function change(color:number,size:number,field:'retail_price'|'barcode'|'incoming_quantity',newValue:string){emit('update:modelValue',props.modelValue.map(c=>c.color_id===color&&c.size_id===size?{...c,[field]:newValue}:c))}
</script>
<template><div class="matrix-scroll"><table class="matrix-table sku-detail-table"><thead><tr><th scope="col">颜色</th><th scope="col">码数</th><th scope="col">条码</th><th scope="col">零售价（元）</th><th v-if="allowReceiving" scope="col">进货数量</th></tr></thead><tbody><tr v-for="{color,size,cell} in rows" :key="`${color.id}:${size.id}`" class="matrix-cell"><th scope="row"><span class="color-swatch" :style="{backgroundColor:color.hex_value||'#cbd5e1'}"/>{{color.name}}</th><td>{{size.name}}</td><td><el-input :disabled="disabled" :id="`barcode-${color.id}-${size.id}`" :model-value="cell?.barcode||''" :placeholder="`${productCode||'款号'}-${color.code}-${size.code}`" :readonly="readonlyDimensions&&Boolean(cell?.id)" maxlength="64" :aria-label="`${color.name}${size.name}条码`" @update:model-value="change(color.id,size.id,'barcode',$event)" /></td><td><el-input :disabled="disabled" :id="`price-${color.id}-${size.id}`" :model-value="cell?.retail_price" inputmode="decimal" :aria-label="`${color.name}${size.name}零售价`" @update:model-value="change(color.id,size.id,'retail_price',$event)" /></td><td v-if="allowReceiving"><el-input :disabled="disabled" :model-value="cell?.incoming_quantity||''" inputmode="numeric" placeholder="留空不进货" :aria-label="`${color.name}${size.name}进货数量`" @update:model-value="change(color.id,size.id,'incoming_quantity',$event)" /></td></tr></tbody></table></div></template>
